'relations',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attacl::text) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(pg_get_constraintdef(x.oid) ORDER BY conname) FROM pg_constraint x WHERE x.conrelid=c.oid)) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname||'.'||c.relname IN('private.accounts_same_world','private.closure_assert_open','private.taxonomy_admission_fingerprint_v1','private.taxonomy_category_path_valid_v1','private.taxonomy_confirmed_worker_modes_v1','private.taxonomy_handoff_valid_v1','private.taxonomy_normalize_v1','private.work_taxonomy_categories','private.work_taxonomy_category_modes','private.work_taxonomy_control','private.work_taxonomy_need_bindings_v1','private.work_taxonomy_need_snapshots','private.work_taxonomy_worker_bindings_v1','private.work_taxonomy_worker_capabilities','private.worker_ai_initial','private.worker_ai_reviews','private.worker_ai_saves','private.worker_ai_service_mode_context_v1','private.worker_ai_sessions','private.worker_ai_source_hash','private.worker_ai_turns','private.worker_execution_mode_choices','public.ai_conversations','public.app_profiles','public.marketplace_responses','public.need_requirement_details','public.needs','public.rpc_open_worker_ai')),
'closure',jsonb_build_object('source',private.closure_source_digest_v5(),'schema',private.closure_schema_digest_v5_139(),'erasure',private.closure_erasure_program_digest_v5(),'certificate',(SELECT sha256 FROM private.closure_source_v5 WHERE singleton),'source_ready',private.retention_ai_source_ready(),'export_binding',private.data_export_policy_binding(),'erasure_binding',private.closure_erasure_binding_v5())) AS capture) x))-'read_only') IS DISTINCT FROM ('{"closure":{"schema":"6603130dcd5df2f0493668e318eee0caffe4c7c249e0f15d6b108537caf2cbe9","source":"da67d3b605b7d5b7e3af8d3264bc55aa87d7249c61436e3ef9d17d5791237a81","erasure":"0935fabefce8549bb2d42dcb3be7cf8c3796ceb5108e87b569f678b09670568b","certificate":"0201a7ccf74a3a5d0ed397d714392881af6ea1056b42f549097f9d3ecd9a4acb","source_ready":false,"export_binding":null,"erasure_binding":null},"functions":[{"md5":"2d6beb6df93bc8eb6ae2622de8319ac5","signature":"private.accounts_same_world(uuid,uuid)","attributes":{"oid":"24330","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"accounts_same_world","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_a","p_b"],"proargtypes":["2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION private.accounts_same_world(p_a uuid, p_b uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog''\nAS $function$\n  select private.account_visibility_world(p_a) = private.account_visibility_world(p_b);\n$function$\n"},{"md5":"1d0e22224d546c4756f216acfe103246","signature":"private.closure_assert_open(uuid,uuid)","attributes":{"oid":"22811","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"closure_assert_open","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":true,"prorettype":"2278","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["a","b"],"proargtypes":["2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":"({CONST :consttype 2950 :consttypmod -1 :constcollid 0 :constlen 16 :constbyval false :constisnull true :location -1 :constvalue <>})","pronargdefaults":1},"definition":"CREATE OR REPLACE FUNCTION private.closure_assert_open(a uuid, b uuid DEFAULT NULL::uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog''\nAS $function$\ndeclare u uuid;\nbegin\n if a is null then raise exception ''CLOSURE_CONTEXT_INVALID'' using errcode=''42501''; end if;\n for u in select distinct x from unnest(array[a,b]) x where x is not null order by x loop\n  perform pg_advisory_xact_lock_shared(private.closure_account_key(u));\n  if private.closure_account_restricted(u) then raise exception ''ACCOUNT_CLOSING'' using errcode=''42501''; end if;\n end loop;\nend;\n$function$\n"},{"md5":"4d0ef4615b244b3a8468f54d04ccf855","signature":"private.taxonomy_admission_fingerprint_v1()","attributes":{"oid":"29325","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"taxonomy_admission_fingerprint_v1","prorows":0,"pronargs":0,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":false,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION private.taxonomy_admission_fingerprint_v1()\n RETURNS text\n LANGUAGE sql\n STABLE\n SET search_path TO ''pg_catalog''\nAS $function$\nSELECT md5(\n coalesce((SELECT string_agg(c.id::text||''/''||c.canonical_key||''/''||\n      coalesce(c.parent_id::text,''ROOT'')||''/''||c.state||''/''||c.catalog_version::text,''|'' ORDER BY c.id::text)\n      FROM private.work_taxonomy_categories c),'''')\n || ''#''\n || coalesce((SELECT string_agg(m.category_id::text||''/''||m.execution_scope,''|'' ORDER BY m.category_id::text,m.execution_scope)\n      FROM private.work_taxonomy_category_modes m),'''')\n || ''#''\n || coalesce((SELECT string_agg(a.category_id::text||''/''||a.locale||''/''||a.normalized_key,''|'' ORDER BY a.category_id::text,a.locale,a.normalized_key)\n      FROM private.work_taxonomy_aliases a),'''')\n);\n$function$\n"},{"md5":"485e0423b3859afd64e3e9a695e4c9f6","signature":"private.taxonomy_category_path_valid_v1(uuid)","attributes":{"oid":"31293","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"taxonomy_category_path_valid_v1","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_category_id"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION private.taxonomy_category_path_valid_v1(p_category_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO ''pg_catalog''\nAS $function$\n WITH RECURSIVE ancestry(id,parent_id,visited) AS (\n   SELECT c.id,c.parent_id,ARRAY[c.id] FROM private.work_taxonomy_categories c\n    WHERE c.id=p_category_id AND c.state=''ESTABLISHED''\n   UNION ALL\n   SELECT c.id,c.parent_id,a.visited||c.id FROM ancestry a\n     JOIN private.work_taxonomy_categories c ON c.id=a.parent_id AND c.state=''ESTABLISHED''\n     WHERE NOT c.id=ANY(a.visited)\n )\n SELECT EXISTS(SELECT 1 FROM ancestry WHERE parent_id IS NULL)\n$function$\n"},{"md5":"de8d37190d70e0534bfc123d7b247b1f","signature":"private.taxonomy_handoff_valid_v1(jsonb)","attributes":{"oid":"31292","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"taxonomy_handoff_valid_v1","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_value"],"proargtypes":["3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION private.taxonomy_handoff_valid_v1(p_value jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE v_city text;\nBEGIN\n IF jsonb_typeof(p_value) IS DISTINCT FROM ''object''\n    OR octet_length(p_value::text)>2048\n    OR jsonb_typeof(p_value->''required'') IS DISTINCT FROM ''boolean''\n    OR p_value-array[''required'',''shippingCountries'',''localExchange'']<>''{}''::jsonb\n THEN RETURN false; END IF;\n IF p_value->''required''=''false''::jsonb THEN RETURN p_value=''{\"required\":false}''::jsonb; END IF;\n IF NOT(p_value?''shippingCountries'' OR p_value?''localExchange'') THEN RETURN false; END IF;\n IF p_value?''shippingCountries'' THEN\n   IF jsonb_typeof(p_value->''shippingCountries'') IS DISTINCT FROM ''array'' THEN RETURN false; END IF;\n   IF jsonb_array_length(p_value->''shippingCountries'') NOT BETWEEN 1 AND 32\n     OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_value->''shippingCountries'') x(value)\n       WHERE jsonb_typeof(x.value) IS DISTINCT FROM ''string'' OR x.value#>>''{}'' !~ ''^[A-Z]{2}$'')\n     OR (SELECT count(DISTINCT x.value) FROM jsonb_array_elements(p_value->''shippingCountries'') x(value))\n         <>jsonb_array_length(p_value->''shippingCountries'')\n   THEN RETURN false; END IF;\n END IF;\n IF p_value?''localExchange'' THEN\n   IF jsonb_typeof(p_value->''localExchange'') IS DISTINCT FROM ''object''\n     OR NOT((p_value->''localExchange'')?&array[''countryCode'',''city''])\n     OR (p_value->''localExchange'')-array[''countryCode'',''city'']<>''{}''::jsonb\n     OR jsonb_typeof(p_value#>''{localExchange,countryCode}'') IS DISTINCT FROM ''string''\n     OR p_value#>>''{localExchange,countryCode}'' !~ ''^[A-Z]{2}$''\n     OR jsonb_typeof(p_value#>''{localExchange,city}'') IS DISTINCT FROM ''string''\n   THEN RETURN false; END IF;\n   v_city:=p_value#>>''{localExchange,city}'';\n   IF v_city IS DISTINCT FROM btrim(v_city,\n      U&''\\0009\\000A\\000B\\000C\\000D\\0020\\00A0\\1680\\2000\\2001\\2002\\2003\\2004\\2005\\2006\\2007\\2008\\2009\\200A\\2028\\2029\\202F\\205F\\3000\\FEFF'')\n      OR char_length(v_city) NOT BETWEEN 3 AND 120\n      OR v_city ~ (''[''||chr(1)||''-''||chr(31)||chr(127)||''-''||chr(159)||''<>0-9]'')\n   THEN RETURN false; END IF;\n END IF;\n RETURN true;\nEND $function$\n"},{"md5":"8185e305017348588028e92397866b35","signature":"private.taxonomy_normalize_v1(text)","attributes":{"oid":"28591","proacl":["postgres=X/postgres","service_role=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"taxonomy_normalize_v1","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":false,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_value"],"proargtypes":["25"],"proisstrict":false,"proparallel":"s","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION private.taxonomy_normalize_v1(p_value text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE PARALLEL SAFE\n SET search_path TO ''pg_catalog''\nAS $function$\n SELECT btrim(regexp_replace(\n   translate(\n     replace(replace(replace(replace(replace(replace(lower(btrim(coalesce(p_value,''''))),\n       ''ђ'',''dj''),''љ'',''lj''),''њ'',''nj''),''џ'',''dz''),''đ'',''dj''),''ß'',''ss''),\n     ''абвгдежзијклмнопрстћуфхцчшčćšž'',\n     ''abvgdezzijklmnoprstcufhccsccsz''\n   ),\n   ''[[:space:]]+'', '' '', ''g''\n ))\n$function$\n"},{"md5":"e74f666d636b83d53e5795450a774202","signature":"private.worker_ai_initial(uuid)","attributes":{"oid":"23016","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"worker_ai_initial","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["aid"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION private.worker_ai_initial(aid uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog''\nAS $function$\ndeclare p public.app_profiles;\nbegin\n select * into p from public.app_profiles where account_id=aid and kind=''WORKER'';\n if found and p.profile_status not in (''DRAFT'',''ACTIVE'') then raise exception ''WORKER_PROFILE_RESTRICTED'' using errcode=''42501''; end if;\n return jsonb_build_object(''displayName'',coalesce(p.display_name,''''),''bio'',coalesce(p.bio,''''),\n  ''skills'',coalesce(to_jsonb(p.skills),''[]''::jsonb),''tools'',coalesce(to_jsonb(p.tools),''[]''::jsonb),\n  ''vehicles'',coalesce(to_jsonb(p.vehicles),''[]''::jsonb),''licenses'',coalesce(to_jsonb(p.licenses),''[]''::jsonb),\n  ''teamCapacity'',coalesce(p.team_capacity,1),''workAreas'',private.worker_saved_areas_v1(aid),\n  ''location'',coalesce(private.worker_location_document(p.id)-array[''profileId'',''accountId'',''revision''],\n    jsonb_build_object(''operatingCountryCode'',null,''city'','''',''radiusKm'',15,''approximatePosition'',null)),\n  ''availability'',coalesce(private.worker_availability_document(p.id)-array[''profileId'',''accountId'',''revision''],\n    jsonb_build_object(''timezone'',''Europe/Belgrade'',''availableNow'',false,''rules'',''[]''::jsonb,''windows'',''[]''::jsonb)));\nend $function$\n"},{"md5":"5bf382a91bc8256cc79bd803b38cd086","signature":"private.worker_ai_service_mode_context_v1(uuid,uuid)","attributes":{"oid":"31166","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"worker_ai_service_mode_context_v1","prorows":0,"pronargs":2,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":false,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_account_id","p_conversation_id"],"proargtypes":["2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION private.worker_ai_service_mode_context_v1(p_account_id uuid, p_conversation_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''pg_catalog''\nAS $function$\nDECLARE\n v_session private.worker_ai_sessions; v_profile_id uuid;\n v_item jsonb; v_projection jsonb; v_hints jsonb; v_source text;\n v_saved_services jsonb:=''[]'';v_draft_services jsonb:=''[]'';v_unresolved jsonb:=''[]'';\n\nBEGIN\n SELECT * INTO v_session FROM private.worker_ai_sessions\n WHERE account_id=p_account_id AND conversation_id=p_conversation_id;\n IF NOT FOUND OR v_session.base_hash IS DISTINCT FROM private.worker_ai_source_hash(p_account_id)\n    OR jsonb_typeof(v_session.candidate->''skills'') IS DISTINCT FROM ''array''\n THEN RAISE EXCEPTION ''WORKER_AI_NOT_EDITABLE'' USING errcode=''55000''; END IF;\n v_profile_id:=v_session.profile_id;\n -- Read only durable, active bindings for independently surviving services.\n -- A newer pending addition is not authority to erase an older bound service.\n -- Source hash above still ties this context to the current owned profile.\n WITH names AS (\n  SELECT skill AS service,private.taxonomy_normalize_v1(skill) AS service_key\n  FROM jsonb_array_elements_text(v_session.candidate->''skills'') n(skill)\n  WHERE EXISTS(SELECT 1 FROM public.app_profiles p WHERE p.id=v_profile_id\n    AND p.account_id=p_account_id AND p.kind=''WORKER'' AND p.profile_status=''ACTIVE''\n    AND (SELECT count(*) FROM unnest(p.skills) saved_skill\n      WHERE private.taxonomy_normalize_v1(saved_skill)=private.taxonomy_normalize_v1(skill))=1)\n ), saved AS (\n  SELECT s.*,r.envelope FROM private.worker_ai_saves s\n  JOIN private.worker_ai_reviews r ON r.id=s.review_id AND r.account_id=s.account_id\n  WHERE s.account_id=p_account_id AND s.receipt->>''profileId''=v_profile_id::text\n   AND (EXISTS(\n    SELECT 1 FROM private.taxonomy_confirmed_worker_modes_v1 m WHERE m.worker_account_id=p_account_id\n     AND m.active AND m.source_review_id=s.review_id AND m.source_request_key=s.client_request_id))\n   AND s.receipt->>''accountId''=p_account_id::text AND s.receipt->>''reviewId''=r.id::text\n   AND s.receipt->''saved''=''true''::jsonb AND s.receipt->''authoritative''=''true''::jsonb\n   AND r.envelope->>''profileId''=v_profile_id::text AND r.envelope->>''accountId''=p_account_id::text\n   AND r.envelope->>''reviewId''=r.id::text AND r.envelope->''canAccept''=''true''::jsonb\n   AND r.created_at<=s.created_at AND s.created_at<=r.expires_at\n   AND r.envelope->>''displayedContentDigest''=encode(extensions.digest(\n     ((r.envelope-''displayedContentDigest'')||jsonb_build_object(''baseHash'',r.base_hash))::text,''sha256''),''hex'')\n\n ), bound AS (\n  SELECT n.service,m.execution_scope AS mode,m.handoff,c.id AS category_id\n  FROM names n JOIN private.work_taxonomy_categories c ON c.state=''ESTABLISHED''\n  JOIN private.work_taxonomy_category_modes cm ON cm.category_id=c.id\n  JOIN private.taxonomy_confirmed_worker_modes_v1 m ON m.category_id=c.id AND m.execution_scope=cm.execution_scope\n   AND m.worker_account_id=p_account_id AND m.active\n  JOIN private.work_taxonomy_worker_capabilities cap ON cap.category_id=c.id AND cap.worker_account_id=p_account_id\n   AND NOT cap.excluded AND cap.origin=''WORKER_CONFIRMED'' AND cap.confirmed_at=m.confirmed_at AND cap.updated_at<=m.confirmed_at\n  JOIN saved s ON s.review_id=m.source_review_id AND s.client_request_id=m.source_request_key\n   AND s.envelope->>''classificationState''=''READY''\n  JOIN private.work_taxonomy_worker_bindings_v1 b ON b.owner_account_id=p_account_id\n   AND b.profile_id=v_profile_id AND b.source_review_id=s.review_id AND b.request_key=s.client_request_id\n   AND b.bound_at=m.confirmed_at AND b.bound_at>=s.created_at\n   AND b.result->>''status''=''BOUND_WORKER_SERVICES'' AND b.result->>''workerProfileId''=v_profile_id::text\n  JOIN private.work_taxonomy_review_batches_v1 batch ON batch.owner_account_id=p_account_id\n   AND batch.source_review_id=s.review_id AND batch.request_key=s.client_request_id AND batch.purpose=''WORKER_CAPABILITY''\n   AND batch.result->>''status''=''COMMITTED'' AND batch.result->''requiresBinding''=''true''::jsonb\n   AND batch.catalog_version=b.catalog_version AND batch.plans=s.envelope->''classificationCandidates''\n   AND batch.review_digest=s.envelope->>''displayedContentDigest''\n   AND jsonb_typeof(batch.plans)=''array'' AND jsonb_typeof(batch.result->''items'')=''array''\n   AND b.result->''serviceModeCount''=to_jsonb(jsonb_array_length(batch.plans))\n   AND jsonb_array_length(batch.result->''items'')=jsonb_array_length(batch.plans)\n   AND jsonb_array_length(s.envelope->''reviewedServiceModes'')=jsonb_array_length(batch.plans)\n  WHERE m.execution_scope IN (''ON_SITE'',''REMOTE'')\n   AND EXISTS(SELECT 1 FROM private.worker_execution_mode_choices choice\n    WHERE choice.worker_profile_id=v_profile_id AND choice.worker_account_id=p_account_id\n     AND choice.consent_source=''EXPLICIT_PROFILE_REVIEW'' AND choice.confirmed_at IS NOT NULL\n     AND m.execution_scope=ANY(choice.modes))\n   -- Compare the saved service key, preserving n.service for display. Formatting\n   -- changes are not a new skill; arbitrary synonyms still require signed IDs.\n   AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(s.envelope#>''{profile,skills}'') skill(value)\n     WHERE private.taxonomy_normalize_v1(skill.value)=n.service_key)\n   AND EXISTS(SELECT 1 FROM jsonb_array_elements(s.envelope->''reviewedServiceModes'') selected(value)\n     WHERE private.taxonomy_normalize_v1(selected.value->>''service'')=n.service_key\n       AND selected.value->>''mode''=m.execution_scope)\n   AND EXISTS(SELECT 1 FROM jsonb_array_elements(batch.result->''items'') result(value)\n     WHERE private.taxonomy_normalize_v1(result.value->>''service'')=n.service_key\n       AND result.value->>''mode''=m.execution_scope AND result.value->>''categoryId''=c.id::text)\n   AND EXISTS(SELECT 1 FROM jsonb_array_elements(batch.plans) plan WHERE private.taxonomy_normalize_v1(plan->>''service'')=n.service_key\n    AND plan->>''mode''=m.execution_scope AND (plan->''handoff'') IS NOT DISTINCT FROM m.handoff)\n   AND (m.handoff IS NULL OR (m.execution_scope=''REMOTE'' AND private.taxonomy_handoff_valid_v1(m.handoff)))\n   AND (SELECT count(*) FROM names same WHERE same.service_key=n.service_key)=1\n   AND (\n    -- Preserve exact/registered-alias resolution, including ambiguity refusal.\n    ((c.canonical_key=n.service_key OR EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a\n       WHERE a.category_id=c.id AND a.normalized_key=n.service_key))\n     AND (SELECT count(*) FROM private.work_taxonomy_categories other WHERE other.state=''ESTABLISHED''\n      AND (other.canonical_key=n.service_key OR EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a\n       WHERE a.category_id=other.id AND a.normalized_key=n.service_key)))=1)\n    OR\n    -- A local signed service may name an already-bound ID without a global alias.\n    -- This branch only describes existing active authority; it never grants it.\n    ((SELECT count(*) FROM private.work_taxonomy_categories other WHERE other.state=''ESTABLISHED''\n      AND (other.canonical_key=n.service_key OR EXISTS(SELECT 1 FROM private.work_taxonomy_aliases a\n       WHERE a.category_id=other.id AND a.normalized_key=n.service_key)))=0\n     AND s.receipt->>''profileStatus''=''ACTIVE''\n     AND private.taxonomy_category_path_valid_v1(c.id)\n     AND NOT EXISTS(SELECT 1 FROM private.work_taxonomy_categories child\n       WHERE child.parent_id=c.id AND child.state=''ESTABLISHED'')\n     AND EXISTS(SELECT 1 FROM jsonb_array_elements(batch.plans) WITH ORDINALITY plan(value,ord)\n       WHERE plan.value->>''action'' IN (''REUSE_EXISTING'',''EXTEND_MODE'')\n        AND private.taxonomy_normalize_v1(plan.value->>''service'')=n.service_key AND plan.value->>''mode''=m.execution_scope\n        AND (plan.value->''handoff'') IS NOT DISTINCT FROM m.handoff\n        AND plan.value->>''categoryId''=c.id::text\n        AND jsonb_typeof(plan.value->''categoryLabel'')=''string''\n        AND c.label IS NOT DISTINCT FROM plan.value->>''categoryLabel''\n        AND plan.value ? ''categoryParentId''\n        AND coalesce(to_jsonb(c.parent_id),''null''::jsonb)\n            IS NOT DISTINCT FROM plan.value->''categoryParentId''\n        AND batch.result->''items''->(plan.ord::integer-1)->>''categoryId''=c.id::text\n        AND batch.result->''items''->(plan.ord::integer-1)->>''mode''=m.execution_scope\n        AND private.taxonomy_normalize_v1(batch.result->''items''->(plan.ord::integer-1)->>''service'')=n.service_key))\n   )\n\n ) SELECT coalesce(jsonb_agg(DISTINCT (jsonb_build_object(''service'',service,''mode'',mode,\n   ''categoryId'',category_id)||CASE WHEN handoff IS NOT NULL THEN jsonb_build_object(''handoff'',handoff)\n     ELSE ''{}''::jsonb END)),''[]''::jsonb) INTO v_saved_services FROM bound;\n\n -- Latest current-source hints are separate proposals. Even an exact category\n -- and mode here are not saved consent and must never replace the baseline.\n v_source:=encode(extensions.digest(convert_to(\n   v_session.candidate::text||''|''||v_session.revision::text||''|''||v_session.base_hash,''UTF8''),''sha256''),''hex'');\n SELECT h.proposals INTO v_hints FROM private.work_taxonomy_gemini_turn_hints_v1 h\n WHERE h.purpose=''WORKER_CAPABILITY'' AND h.account_id=p_account_id\n   AND h.conversation_id=p_conversation_id AND h.source_fingerprint=v_source\n   AND h.catalog_version=(SELECT catalog_version FROM private.work_taxonomy_control WHERE singleton=true)\n ORDER BY h.created_at DESC,h.id DESC LIMIT 1;\n IF jsonb_typeof(v_hints)=''array'' THEN\n   FOR v_item IN SELECT value FROM jsonb_array_elements(v_hints) LOOP\n     IF v_item->>''action'' IS DISTINCT FROM ''REUSE_EXISTING''\n        OR v_item->>''mode'' NOT IN (''ON_SITE'',''REMOTE'')\n        OR v_item->>''categoryId'' IS NULL\n        OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_session.candidate->''skills'') skill(value)\n          WHERE skill.value=to_jsonb(v_item->>''service''))\n        OR (SELECT count(*) FROM jsonb_array_elements(v_session.candidate->''skills'') skill(value)\n            WHERE private.taxonomy_normalize_v1(skill.value#>>''{}'')=\n                  private.taxonomy_normalize_v1(v_item->>''service''))<>1\n     THEN CONTINUE; END IF;\n     v_projection:=private.taxonomy_review_exact_projection_v1(''WORKER_CAPABILITY'',\n       jsonb_build_array(v_item->>''service''),jsonb_build_array(\n         jsonb_build_object(''service'',v_item->>''service'',''mode'',v_item->>''mode'')));\n     IF v_projection->>''status''=''READY''\n        AND v_projection#>>''{classificationCandidates,0,categoryId}''=v_item->>''categoryId''\n     THEN v_draft_services:=v_draft_services||jsonb_build_array(jsonb_build_object(\n       ''service'',v_item->>''service'',''mode'',v_item->>''mode'',''categoryId'',v_item->>''categoryId'')\n        ||case when v_item ? ''handoff'' then jsonb_build_object(''handoff'',v_item->''handoff'') else ''{}''::jsonb end);\n     END IF;\n   END LOOP;\n END IF;\n SELECT coalesce(jsonb_agg(value ORDER BY value->>''service'',value->>''mode'',value->>''categoryId''),''[]''::jsonb)\n INTO v_saved_services FROM (SELECT DISTINCT value FROM jsonb_array_elements(v_saved_services)) rows;\n SELECT coalesce(jsonb_agg(value ORDER BY value->>''service'',value->>''mode'',value->>''categoryId''),''[]''::jsonb)\n INTO v_draft_services FROM (SELECT DISTINCT value FROM jsonb_array_elements(v_draft_services)) rows;\n SELECT coalesce(jsonb_agg(value ORDER BY value#>>''{}''),''[]''::jsonb) INTO v_unresolved\n FROM (SELECT DISTINCT skill.value FROM jsonb_array_elements(v_session.candidate->''skills'') skill(value)\n   WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_saved_services||v_draft_services) known(value)\n     WHERE known.value->>''service''=skill.value#>>''{}'')) unresolved;\n RETURN jsonb_build_object(''schemaVersion'',''WORKER_SERVICE_MODE_CONTEXT_V1'',''revision'',v_session.revision,\n   ''savedServices'',v_saved_services,''draftServices'',v_draft_services,''unresolvedServices'',v_unresolved);\nEND $function$\n"},{"md5":"d50edbb9666e5d0e5e12ec2dca18172e","signature":"private.worker_ai_source_hash(uuid)","attributes":{"oid":"23015","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"worker_ai_source_hash","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":true,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["aid"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"18078","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION private.worker_ai_source_hash(aid uuid)\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog''\nAS $function$\n select encode(extensions.digest(coalesce(private.worker_ai_source(aid),''null''::jsonb)::text,''sha256''),''hex'');\n$function$\n"},{"md5":"7b0d972e34fc970a9521c0c6131130d1","signature":"public.rpc_open_worker_ai(uuid)","attributes":{"oid":"23023","proacl":["postgres=X/postgres","authenticated=X/postgres","service_role=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13619","proname":"rpc_open_worker_ai","prorows":0,"pronargs":1,"proowner":"16388","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_client_request_id"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"definition":"CREATE OR REPLACE FUNCTION public.rpc_open_worker_ai(p_client_request_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog''\nAS $function$\ndeclare u uuid:=auth.uid(); cid uuid; pid uuid; candidate jsonb;\nbegin\n if u is null then raise exception ''AUTH_REQUIRED'' using errcode=''42501''; end if;\n if p_client_request_id is null then raise exception ''WORKER_AI_ID_REQUIRED'' using errcode=''22023''; end if;\n perform private.closure_assert_open(u);\n perform pg_advisory_xact_lock(hashtextextended(''worker-ai-open:''||u::text,0));\n select s.conversation_id into cid from private.worker_ai_sessions s where s.account_id=u and s.open_request_id=p_client_request_id;\n if cid is not null then return private.worker_ai_document(cid); end if;\n select s.conversation_id into cid from private.worker_ai_sessions s join public.ai_conversations c on c.id=s.conversation_id\n  where s.account_id=u and c.status=''OPEN'' order by s.created_at desc limit 1;\n if cid is not null then return private.worker_ai_document(cid); end if;\n select id into pid from public.app_profiles where account_id=u and kind=''WORKER'' for update;\n candidate:=private.worker_ai_initial(u); pid:=coalesce(pid,extensions.gen_random_uuid());\n insert into public.ai_conversations(account_id,purpose) values(u,''PROFILE'') returning id into cid;\n insert into private.worker_ai_sessions(conversation_id,account_id,open_request_id,profile_id,base_hash,candidate)\n values(cid,u,p_client_request_id,pid,private.worker_ai_source_hash(u),candidate);\n return private.worker_ai_document(cid);\nend $function$\n"}],"read_only":"on","relations":[{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"name":"private.taxonomy_confirmed_worker_modes_v1","owner":"postgres","columns":[["worker_account_id","uuid",true,null],["category_id","uuid",true,null],["execution_scope","text",true,null],["source_review_id","uuid",true,null],["source_request_key","uuid",true,null],["confirmed_at","timestamp with time zone",true,null],["active","boolean",true,null],["handoff","jsonb",false,null]],"force_rls":false,"constraints":["FOREIGN KEY (worker_account_id, category_id) REFERENCES private.work_taxonomy_worker_capabilities(worker_account_id, category_id) ON DELETE RESTRICT","FOREIGN KEY (category_id, execution_scope) REFERENCES private.work_taxonomy_category_modes(category_id, execution_scope) ON DELETE RESTRICT","CHECK ((execution_scope = ANY (ARRAY[''REMOTE''::text, ''ON_SITE''::text])))","PRIMARY KEY (worker_ac